//! `DateTime::diff()`, `DateInterval::format()` and `add()` / `sub()` against PHP 8.5.13
//! (`tests/vectors/diff.json`, generated by `diff.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh diff`).

mod common;

use common::*;
use twig_date::{DateObject, IntervalObject, TimeZoneObject, classes};
use twig_value::{ObjectRef, Value};

fn date_at(c: &Ctx, zone: &str, ts: i64, us: i64) -> ObjectRef {
    let mut diags = Vec::new();
    let d = DateObject::construct(
        &c.ctx,
        classes::datetime(),
        format!("@{ts}").as_bytes(),
        None,
    )
    .unwrap();
    let tz = TimeZoneObject::construct(&c.ctx, zone.as_bytes()).unwrap();
    call(&d, "setTimezone", vec![Value::Object(tz)], &mut diags).unwrap();
    call(&d, "setMicrosecond", vec![Value::Int(us)], &mut diags).unwrap();
    d
}

#[test]
fn diff_and_interval_format() {
    let v = load("diff");
    let fmt = s(&v["fmt"]);
    let c = Ctx::new();
    let mut r = Report::new("diff()");
    for case in v["diff"].as_array().unwrap() {
        let a = date_at(&c, s(&case[0]), i(&case[1]), i(&case[2]));
        let b = date_at(&c, s(&case[3]), i(&case[4]), i(&case[5]));
        for (k, absolute) in [false, true].into_iter().enumerate() {
            let iv = obj(call(
                &a,
                "diff",
                vec![Value::Object(b.clone()), Value::Bool(absolute)],
                &mut Vec::new(),
            )
            .unwrap());
            let got = str_val(&call(&iv, "format", vec![php_str(fmt)], &mut Vec::new()).unwrap());
            r.eq(got, s(&case[6 + k]).to_owned(), || {
                format!("{case} absolute={absolute}")
            });
        }
    }
    r.finish();
}

#[test]
fn add_and_sub() {
    let v = load("diff");
    let c = Ctx::new();
    let mut r = Report::new("add()/sub()");
    for case in v["addsub"].as_array().unwrap() {
        let (zone, ts, us) = (s(&case[0]), i(&case[1]), i(&case[2]));
        let interval = || -> ObjectRef {
            match s(&case[3]) {
                "iso" => {
                    let spec = s(&case[4]);
                    let (spec, invert) = match spec.strip_suffix("/invert") {
                        Some(sp) => (sp, true),
                        None => (spec, false),
                    };
                    let iv = IntervalObject::construct(&c.ctx, spec.as_bytes()).unwrap();
                    if invert {
                        iv.write_property(b"invert", Value::Int(1), &mut Vec::new())
                            .unwrap();
                    }
                    iv
                }
                "str" => {
                    IntervalObject::create_from_date_string(&c.ctx, s(&case[4]).as_bytes()).unwrap()
                }
                _ => {
                    let other = date_at(&c, s(&case[4][0]), i(&case[4][1]), 0);
                    let base = date_at(&c, zone, ts, us);
                    obj(call(&base, "diff", vec![Value::Object(other)], &mut Vec::new()).unwrap())
                }
            }
        };
        for (k, method) in ["add", "sub"].into_iter().enumerate() {
            let d = date_at(&c, zone, ts, us);
            let got = match call(&d, method, vec![Value::Object(interval())], &mut Vec::new()) {
                Ok(_) => show(&d),
                Err(e) => exc(&e),
            };
            r.eq(got, s(&case[5 + k]).to_owned(), || {
                format!("{method} {case}")
            });
        }
    }
    r.finish();
}
